{
  "category_edits": [
    {
      "category": "sequence_interest",
      "rationale": "Test whether a 2.5-interaction causal pooling half-life sharpens recent interests across all four datasets while retaining the 0.8 current-state and 0.2 pooled-state blend. Preserve padding exclusion, final-real-position readout, and all other model and training settings.",
      "edits": [
        {
          "find": "weights = torch.exp2(-distances.clamp(min=0).to(out.dtype) / 3.0)",
          "replace": "weights = torch.exp2(-distances.clamp(min=0).to(out.dtype) / 2.5)"
        },
        {
          "find": "\"sequence_readout\": \"gru_0.8_causal_mean_0.2_half_life_3\",",
          "replace": "\"sequence_readout\": \"gru_0.8_causal_mean_0.2_half_life_2.5\","
        },
        {
          "find": "if meta.get(\"sequence_readout\") != \"gru_0.8_causal_mean_0.2_half_life_3\":",
          "replace": "if meta.get(\"sequence_readout\") != \"gru_0.8_causal_mean_0.2_half_life_2.5\":"
        }
      ]
    }
  ],
  "change_summary": "Shorten only causal pooling half-life from 3 to 2.5 interactions and synchronize checkpoint metadata with the embedded predictor. Retain one GRU4Rec checkpoint per dataset."
}
